// The free weather textures shipped in assets/weather/ (generated by scripts/make-weather-assets.mjs), exposed as the
// {assetBaseUrl, fetch, loadTexture} trio createThreeWeather takes. File names follow the drop-in convention the adapter
// expects (enviro-cloud-*.rgba, galaxy.jpg …) and are mapped to the bundled files here; a private asset set wins when given.
import * as THREE from 'three';

const file = name => new URL(`../../../assets/weather/${name}`, import.meta.url).href;
export const BUNDLED_WEATHER_FILES = Object.freeze({
  'enviro-cloud-base-64.rgba': file('cloud-base-64.rgba'),
  'enviro-cloud-detail-32.rgba': file('cloud-detail-32.rgba'),
  'cirrus.png': file('cirrus.png'), 'moon.png': file('moon.png'), 'stars.png': file('stars.png'),
  'galaxy.jpg': file('galaxy.png'), 'weather-map.png': file('weather-map.png'),
});
export const BUNDLED_WEATHER_BASE = 'bundled://weather/';
const resolve = url => BUNDLED_WEATHER_FILES[String(url).split('/').pop()] ?? url;

export function bundledWeatherAssets({loader = new THREE.TextureLoader(), fetch: fetcher = (...a) => globalThis.fetch(...a)} = {}) {
  return {
    assetBaseUrl: BUNDLED_WEATHER_BASE,
    fetch: (url, init) => fetcher(resolve(url), init),
    loadTexture: url => loader.loadAsync(resolve(url)),
  };
}
